#!/usr/bin/env python3
"""Render the scene-1 v0.4 causal attribution audit."""

from __future__ import annotations

import argparse
import json
from pathlib import Path


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--input-json",
        type=Path,
        default=Path(
            "data/processed/causal_attribution_v0_4/"
            "causal_attribution_v0_4.json"
        ),
    )
    parser.add_argument(
        "--output-html",
        type=Path,
        default=Path(
            "data/processed/causal_attribution_v0_4/"
            "causal_attribution_v0_4_audit.html"
        ),
    )
    return parser.parse_args()


